#!/usr/bin/env python3
"""Print the next order id."""

import string


def to_base36(n: int, width: int = 4) -> str:
    """Encode integer as zero-padded base-36 string."""
    digits = string.digits + string.ascii_uppercase
    buf = []
    for _ in range(width):
        buf.append(digits[n % 36])
        n //= 36
    return "".join(reversed(buf))


def main() -> None:
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        # No ids yet – start at the first one
        next_suffix = "0000"
    else:
        last_id = lines[-1]
        last_num = int(last_id.removeprefix("ORD-"), 36)
        next_suffix = to_base36(last_num + 1)

    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

