"""Read ids.txt and print the next order id."""

import sys

ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
BASE = len(ALPHABET)  # 32
ID_LEN = 4


def _to_number(s: str) -> int:
    n = 0
    for ch in s:
        n = n * BASE + ALPHABET.index(ch)
    return n


def _from_number(n: int) -> str:
    chars = []
    for _ in range(ID_LEN):
        chars.append(ALPHABET[n % BASE])
        n //= BASE
    return "".join(reversed(chars))


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1]
    if not last_id.startswith("ORD-"):
        print(f"Unexpected id format: {last_id}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    if len(suffix) != ID_LEN:
        print(f"Unexpected id length: {last_id}", file=sys.stderr)
        sys.exit(1)

    n = _to_number(suffix)
    n += 1
    next_id = "ORD-" + _from_number(n)
    print(next_id)


if __name__ == "__main__":
    main()

