import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"

def base36_inc(s: str) -> str:
    """Increment a base-36 string of fixed length."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        idx = BASE36.index(chars[i])
        if idx < 35:
            chars[i] = BASE36[idx + 1]
            return "".join(chars)
        else:
            chars[i] = "0"
    # All carried — wrap to all zeros (shouldn't happen in practice)
    return "0" * len(s)

def main():
    try:
        with open("ids.txt", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("ORD-0000")
        return

    last_id = None
    for line in lines:
        stripped = line.strip()
        if stripped and "ORD-" in stripped:
            parts = stripped.split()
            for part in parts:
                if part.startswith("ORD-"):
                    last_id = part

    if last_id is None:
        print("ORD-0000")
        return

    suffix = last_id[4:]  # e.g., "243G"
    next_suffix = base36_inc(suffix)
    print(f"ORD-{next_suffix}")

if __name__ == "__main__":
    main()
