import sys

CHARS = 4

def to_base36(n: int) -> str:
    """Convert an integer to a zero-padded uppercase base-36 string."""
    chars = []
    for _ in range(CHARS):
        n, rem = divmod(n, 36)
        chars.append("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[rem])
    return "".join(reversed(chars))


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    last = lines[-1]
    if not last.startswith("ORD-") or len(last) != 8:
        print(f"Invalid id format: {last!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last[4:]
    try:
        value = int(suffix, 36)
    except ValueError:
        print(f"Invalid id suffix: {suffix!r}", file=sys.stderr)
        sys.exit(1)

    next_val = value + 1
    next_id = "ORD-" + to_base36(next_val)
    print(next_id)


if __name__ == "__main__":
    main()

