#!/usr/bin/env python3
"""Read attendees.txt (UTF-8, one name per line) and write roster.txt
sorted alphabetically using a casefold, accent-insensitive sort key."""

import unicodedata


def sort_key(name):
    """Return a sort key that is case-insensitive and accent-insensitive."""
    # NFKD decomposition separates base characters from combining marks
    nfkd = unicodedata.normalize("NFKD", name)
    # Strip combining marks (accents, etc.)
    stripped = "".join(c for c in nfkd if not unicodedata.combining(c))
    return stripped.casefold()


def main():
    with open("attendees.txt", encoding="utf-8") as f:
        names = [line.strip() for line in f if line.strip()]

    names.sort(key=sort_key)

    with open("roster.txt", "w", encoding="utf-8", newline="") as f:
        for name in names:
            f.write(name + "\n")


if __name__ == "__main__":
    main()

