"""Weekly ops report: aggregate measurements from inbox/ into report.txt."""

from pathlib import Path

def main():
    inbox = Path("inbox")
    values = []

    for txt_file in sorted(inbox.glob("*.txt")):
        for line in txt_file.read_text().strip().splitlines():
            if line.strip():
                values.append(int(line.strip()))

    entries = len(values)
    total = sum(values)
    average = total / entries if entries > 0 else 0.0

    report = Path("report.txt")
    report.write_text(
        f"entries {entries}\n"
        f"total {total}\n"
        f"average {average:.2f}\n"
    )

if __name__ == "__main__":
    main()

