#!/usr/bin/env python3
"""Weekly ops report: read inbox .txt files and write report.txt."""

import os
import glob

def main():
    inbox_dir = "inbox"
    txt_files = sorted(glob.glob(os.path.join(inbox_dir, "*.txt")))

    entries = 0
    total = 0

    for fpath in txt_files:
        with open(fpath) as f:
            for line in f:
                line = line.strip()
                if line == "":
                    continue
                try:
                    val = int(line)
                except ValueError:
                    continue
                entries += 1
                total += val

    if entries > 0:
        avg = total / entries
    else:
        avg = 0.0

    with open("report.txt", "w") as f:
        f.write(f"entries {entries}\n")
        f.write(f"total {total}\n")
        f.write(f"average {avg:.2f}\n")

if __name__ == "__main__":
    main()

